    getpa = freq.GetCommonParams()
    getpa = string(getpa)

    paths222 = freq.GetPath()
    hou = ["js"]
    println(paths222)
    println("开始判定后缀")
    for i in hou {
        println(i)
        println(paths222.Split(".")[-1])
        if paths222.Split(".")[-1] == i {
            println("后缀处于黑名单，跳过扫描")
            return
        }
        
    }
    

    if poc.GetHTTPRequestPath(req).Split("/")[-1] == "" {
        paths222 += addr
        paths222 += getpa
        println(paths222)
        paths222 = codec.Md5(paths222 + "sql")
    } else {
        paths222 = poc.GetHTTPRequestPath(req).Split("?")[0]
