            }
            
            jj, _ = param22.Fuzz(i).Results()

            hj += jj
        }
        

        for _, req123 := range hj {
            
            println(req123)
            ttt, rrr, err = poc.HTTPEx(req123, poc.https(isHttps), poc.retryTimes(3), poc.retryInStatusCode(502))
            if err{
