            rspIns = poc.ParseBytesToHTTPResponse(ttt.RawPacket)~
            reqIns = poc.ParseBytesToHTTPRequest(ttt.RawRequest)~
            jhsjk = false
            for i in respayload {
                if i in ttt.RawPacket {
                    jhsjk = true
                }
                
            }
            

            tmppayload = reqIns.FormValue(param22.Name())
            tmppayload=tmppayload.ReplaceAll(" ", "+")
            if (ttt.TraceInfo.GetServerDurationMS() > 3000 && ttt.TraceInfo.GetServerDurationMS() < 9000) || jhsjk {
                if !jhsjk {
                    tmppayload = tmppayload.Replace("3", "5")
                    println(tmppayload)
                    param22.Fuzz(tmppayload).Show()
                    jj, _ = param22.Fuzz(tmppayload).Results()
                    kk = ""
                    for _, uu := range jj {
