                    ttt2, rrr2, _ = poc.HTTPEx(kk, poc.https(isHttps), poc.retryTimes(3), poc.retryInStatusCode(502))
                    rspIns2 = poc.ParseBytesToHTTPResponse(ttt2.RawPacket)~
