                    if (ttt2.TraceInfo.GetServerDurationMS() > 5000 && ttt2.TraceInfo.GetServerDurationMS() < 15000) {
                        ttt3, rrr2, _ = poc.HTTPEx(kk, poc.https(isHttps))
                        if (ttt3.TraceInfo.GetServerDurationMS() > 5000 && ttt3.TraceInfo.GetServerDurationMS() < 15000) {
                            println("成功检测到漏洞")
                            risk.NewRisk(
                                reqIns.URL.Host, 
