                                risk.severity("critical"), 
                                risk.parameter(param22.Name()), 
                                risk.payload(reqIns2.FormValue(param22.Name())), 
                                risk.description("sql注入漏洞"), 
                                risk.solution("屏蔽相关关键词"), 
                                risk.typeVerbose("sql注入"), 
                                risk.request(ttt2.RawRequest), 
                                risk.type("sqlinjection"), 
                                risk.response(ttt2.RawPacket), 
                            )
                            break
                        }
                        
                    }
                    
                } else {
                    println("成功检测到漏洞")
                    risk.NewRisk(
                        reqIns.URL.Host, 
                        risk.title("sql注入: %v" % reqIns.URL.String()), 
                        risk.severity("critical"), 
                        risk.parameter(param22.Name()), 
                        risk.payload(reqIns.FormValue(param22.Name())), 
                        risk.description("sql注入漏洞"), 
                        risk.solution("屏蔽相关关键词"), 
                        risk.typeVerbose("sql注入"), 
                        risk.request(ttt.RawRequest), 
                        risk.type("sqlinjection"), 
                        risk.response(ttt.RawPacket), 
                    )
                    break
                }
                
            }
            

            freq.FuzzGetParams(param22.Name(), valee)
        }
        
    }
    
